using UnityEngine;

namespace LightingBlocks
{
    // Clips are generated by Tools/audio/build_audio.py and loaded from
    // Resources so the code-generated scenes need no wiring in the setup scripts.
    public static class GameAudio
    {
        public const float MusicVolume = .18f;
        public const float SfxVolume = .22f;

        static AudioClip[] footsteps;
        static AudioClip grab;
        static AudioSource music;

        public static AudioClip[] Footsteps
        {
            get
            {
                if (footsteps != null) return footsteps;
                var list = new System.Collections.Generic.List<AudioClip>();
                for (int i = 1; i <= 5; i++)
                {
                    var clip = Resources.Load<AudioClip>("Audio/SFX/footstep_stone_" + i.ToString("00"));
                    if (clip != null) list.Add(clip);
                }
                footsteps = list.ToArray();
                return footsteps;
            }
        }

        public static AudioClip Grab => grab != null ? grab : grab = Resources.Load<AudioClip>("Audio/SFX/grab_attune");

        // The chapters differ in weight, not in sample: Soul Bridge stone is
        // heavier than Last Spark crystal, so the same assets are pitched down.
        public static float StepPitch => SoulBridgeGame.Instance != null ? .92f : 1f;
        public static float GrabPitch(PullableBox box) =>
            box != null && box.GetComponent<SoulBridgeBlock>() != null ? .667f : 1f;

        public static void PlayMusic(string clipName)
        {
            var clip = Resources.Load<AudioClip>("Audio/Music/" + clipName);
            if (clip == null) return;
            if (music == null)
            {
                var host = new GameObject("Music");
                host.transform.SetParent(null);
                music = host.AddComponent<AudioSource>();
                music.spatialBlend = 0; music.loop = true; music.volume = MusicVolume;
                music.playOnAwake = false; music.priority = 0;
            }
            if (music.clip == clip && music.isPlaying) return;
            music.clip = clip; music.Play();
        }

        public static void StopMusic() { if (music != null) music.Stop(); }
    }
}
